Let $\bm{Z}^{(\lambda)}$ denote (any) global minimum of $g^{(\lambda)}_{{\sf cvx}}$, and let $\bm{U}^{(\lambda)}$ denote any critical point of $f^{(\lambda)}_{{\sf ncvx}}$ satisfying the first and second-order necessary conditions for a local minimum.  Then under 2, 3, 
on the event $\mathcal{E}_{{\sf Good}}$ defined in (egood), 
\begin{align}
    \bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top} &= \bm{Z}^{(\lambda)}.
\end{align}

On the event $\mathcal{E}_{{\sf Good}}$, under 2, 3 it holds that 
   \begin{align}
         \bm{Z}_{{\sf deb}}^{(\lambda)} &= \bm{V}_{U} \big( \bm{ \Sigma}+ \lambda \bm{I} \big) \bm{V}_U^{\top}, 
     \end{align}
     where $\bm{V}_U \bm{\Sigma}^{1/2} \bm{W}_U^{\top}$ is the singular value decomposition of $\bm{U}^{(\lambda)}$.   Furthermore, on this same event it holds that 
 \begin{align}
     \bm{U}_{{\sf deb}}^{(\lambda)} \bm{U}_{{\sf deb}}^{(\lambda)\top} &= \bm{Z}_{{\sf deb}}^{(\lambda)}. 
     \end{align}

Suppose that 1, 2, 3 are satisfied. Then for any 1-Lipschitz function $\phi: \mathbb{R}^{d \times d} \to \mathbb{R}$ and for any $\ensuremath{\varepsilon}$ satisfying $\ensuremath{\varepsilon} > C \exp( - c d r)$, it holds that
\begin{align}
   \mathbb{P}\bigg\{ &\bigg| \phi\bigg( \frac{1}{\sqrt{dr}} \bm{U}^{(\lambda) } \bm{U^}{(\lambda)\top} \bigg) - \mathbb{E}_{\bm{H}} \phi\bigg( \frac{1}{\sqrt{dr}} \bm{Z}^{(\lambda/\zeta^*)}_{{\sf ST}}(\tau^*) \bigg) \bigg| > \ensuremath{\varepsilon} \bigg\}\\
   &\leq  O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) - \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg),
\end{align}
where the constants depend on problem parameters.  The same result holds if $\bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top}$ is replaced with $\bm{Z}^{(\lambda)}$.

Suppose that 1, 2, 3 are satisfied. Then for any $1$-Lipschitz function $\phi: \mathbb{R}^{d\times d} \to \mathbb{R}$ it holds that
    \begin{align}
         \bigg| \mathbb{E} \phi \big( \bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)/\sqrt{dr} \big) - \mathbb{E} \phi \big( \bm{Z}_{{\sf ST}}^{(\lambda)}/\sqrt{dr} \big) \bigg| = O\bigg( \sigma \frac{d r^{3/2}}{n}\bigg).
    \end{align}

Suppose that 1, 2, 3 are satisfied.
Let $\bm{Z}^{(\lambda)}_{{\sf deb}}$ denote the debiased convex estimator.  Let $\phi$ be any $1$-Lipschitz function on $\mathbb{R}^{d \times d}$.  Then
\begin{align}
    \mathbb{P}\bigg\{ \bigg|   &\phi\bigg( \frac{1}{\sqrt{dr}}\bm{ Z}^{(\lambda)}_{{\sf deb}} \bigg) - \mathbb{E}_{\bm{H}} \phi\bigg( \frac{1}{\sqrt{dr}}\bm{Z}^{(\lambda)}_{\sf HT} \bigg) \bigg| > \ensuremath{\varepsilon} \bigg\} \\
    &\leq  O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) - \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg).
\end{align}

Suppose that 1, 2, 3 are satisfied. Then for any $1$-Lipschitz function $\phi: \mathbb{R}^{d\times d} \to \mathbb{R}$ it holds that
    \begin{align}
         \bigg| \mathbb{E} \phi \big( \bm{Z}_{{\sf HT}}^{(\lambda)}/\sqrt{dr} \big) - \mathbb{E} \phi \big( \bm{Z}_{{\sf HT}}^{}/\sqrt{dr} \big) \bigg| = O\bigg( \sigma\frac{dr}{n} \bigg).
    \end{align}

Suppose that 1, 2, 3 are satisfied.  Then the debiased estimator $\bm{U}^{(\lambda)}_{{\sf deb}}$ satisfies the bound
    \begin{align}
      \frac{1}{\sqrt{dr}}   \|\bm{U}^{(\lambda)}_{{\sf deb}} \bm{U}^{(\lambda)\top}_{{\sf deb}} - \bm{U}^{(0)} \bm{U}^{(0)\top}\|_F = O\bigg( \sigma r\sqrt{\frac{d}{n}} \bigg)
    \end{align}
    with probability at least $1 - O\bigg( \exp( - c dr) + \exp(- c n) + \exp( - c d) \bigg)$.

Suppose that 1, 2, 3 hold. 
There exists a constant $C > 0$ depending on our assumptions such that for all $n$ sufficiently large, 
for any $\ensuremath{\varepsilon}> C\exp( - c dr )$, and for any $1-$Lipschitz function $\phi: \mathbb{R}^{d\times d} \to \mathbb{R}$,
\begin{align}
\begin{split}
    \mathbb{P}\bigg\{ &\bigg| \phi\bigg( \frac{1}{\sqrt{dr}}\bm{U}^{(0)} \bm{U}^{(0)\top} \bigg) - \mathbb{E}_{\bm{H}} \phi\big( \frac{1}{\sqrt{dr}}\bm{Z}_{{\sf HT}} \big) \bigg| > \ensuremath{\varepsilon} + C \sigma \sqrt{\frac{r}{\gamma_n}}\bigg\} \\&\leq  
 O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) + \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg); \end{split} \\
 \begin{split}
    \mathbb{P}\bigg\{ &\bigg| \phi\bigg( \frac{1}{\sqrt{dr}}\bm{Z}^{(\lambda)} \bigg) - \mathbb{E}_{\bm{H}} \phi\big( \frac{1}{\sqrt{dr}}\bm{Z}_{{\sf ST}}^{(\lambda)} \big) \bigg| > \ensuremath{\varepsilon} + C \sigma \frac{\sqrt{r}}{\gamma_n}  \bigg\} \\
    &\leq  O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) + \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg) \end{split}
\end{align}
The same result continues to hold if $\bm{Z}^{(\lambda)}$ is replaced with $\bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top}$.

